begin;
\ir fixtures/clinical.sql
reset role;
update public.memberships set capabilities=array['worklists.read','patients.read']where id=pg_temp.id(201);
update public.membership_locations set capabilities=array['worklists.read','patients.read']where membership_id=pg_temp.id(201);
create function pg_temp.task_input(assignee integer default 3,patient boolean default true)returns jsonb language sql as $$select jsonb_build_object('kind','appointment_follow_up','patient_id',case when patient then pg_temp.patient()end,'assignee_user_id',pg_temp.id(assignee),'due_day',(clock_timestamp()at time zone'Etc/UTC')::date+1,'due_minute',540,'location_version',1)$$;
create function pg_temp.task(n integer,ver integer,action text,k integer,input jsonb default'{}')returns jsonb language sql as $$select public.doctor_worklist_command(pg_temp.practice(),pg_temp.location(),pg_temp.id(n),ver,action,input,pg_temp.id(k))$$;
set local role authenticated;select pg_temp.claim(1);
select pg_temp.command('create',jsonb_build_object('patient_id',pg_temp.patient(),'snapshot',pg_temp.snapshot()),1900);
select ok(pg_temp.detail()::text like'%Synthetic entered note%','private synthetic note exists before administrative projection test');
select is(pg_temp.task(900,0,'create',920,pg_temp.task_input())->>'state','assigned','C01: explicit patient follow-up assigned');
select is(pg_temp.task(900,0,'create',920,pg_temp.task_input())->>'version','1','exact creation receipt returns one task');
select throws_ok($$select pg_temp.task(900,0,'create',920,pg_temp.task_input()||'{"kind":"general_administration"}')$$,'22023','DOCTOR_IDEMPOTENCY_CONFLICT','creation receipt cannot change material');
select throws_ok($$select pg_temp.task(901,0,'create',921,pg_temp.task_input()||'{"notes":"clinical note"}')$$,'22023','DOCTOR_WORKLIST_INVALID','clinical/free text keys refused');
select throws_ok($$select pg_temp.task(901,0,'create',921,pg_temp.task_input()||'{"kind":"diagnosis"}')$$,'22023','DOCTOR_WORKLIST_INVALID','medical purpose refused');
select throws_ok($$select pg_temp.task(901,0,'create',921,pg_temp.task_input()||'{"due_minute":1440}')$$,'22023','DOCTOR_WORKLIST_INVALID','due minute cannot silently become next day');
select throws_ok($$select pg_temp.task(901,0,'create',921,pg_temp.task_input()||'{"location_version":99}')$$,'40001','DOCTOR_WORKLIST_CONFLICT','captured clinic version checked');
select throws_ok($$select pg_temp.task(900,1,'complete',921)$$,'42501','DOCTOR_ACCESS_DENIED','manager cannot complete another assignee work');
select is(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',false,false)->>'total','1','manager sees scoped population');
select pg_temp.claim(2);
select throws_ok($$select public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',false,false)$$,'42501','DOCTOR_ACCESS_DENIED','foreign owner denied directory');
select pg_temp.claim(3);
select ok(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',false,false)::text not like'%Synthetic entered note%','administrative projection excludes a persisted private clinical note');
select is(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',false,false)->>'total','1','worklist reader needs no appointments grant');
select throws_ok($$select pg_temp.task(901,0,'create',921,pg_temp.task_input())$$,'42501','DOCTOR_ACCESS_DENIED','reader cannot assign tasks');
select is(pg_temp.task(900,1,'start',922)->>'state','in_progress','assignee starts administrative work');
select is(pg_temp.task(900,2,'complete',923)->>'state','completed','assignee completes work');
select is(pg_temp.task(900,2,'complete',923)->>'version','3','same completion receipt replays exactly');
select throws_ok($$select pg_temp.task(900,2,'complete',924)$$,'40001','DOCTOR_WORKLIST_CONFLICT','different duplicate completion rejected');
select is(public.doctor_worklist_history(pg_temp.practice(),pg_temp.location(),pg_temp.id(900),0)->>'total','3','completion replay adds no event');
select pg_temp.claim(1);select pg_temp.task(901,0,'create',925,pg_temp.task_input());
select is(pg_temp.task(901,1,'reassign',926,jsonb_build_object('assignee_user_id',pg_temp.id(1),'reason','workload'))->>'version','2','C02: reassign changes version atomically');
select is(public.doctor_worklist_history(pg_temp.practice(),pg_temp.location(),pg_temp.id(901),0)#>>'{events,0,previous_assignee}',pg_temp.id(3)::text,'immutable history retains old assignment');
select is(public.doctor_worklist_history(pg_temp.practice(),pg_temp.location(),pg_temp.id(901),0)#>>'{events,0,actor_user_id}',pg_temp.id(1)::text,'immutable history retains actor');
select pg_temp.claim(3);
select is(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',false,false)->>'total','1','old assignee loses reassigned task');
select throws_ok($$select public.doctor_worklist_history(pg_temp.practice(),pg_temp.location(),pg_temp.id(901),0)$$,'42501','DOCTOR_ACCESS_DENIED','old assignee cannot open retained protected history');
select throws_ok($$select pg_temp.task(901,1,'complete',927)$$,'42501','DOCTOR_ACCESS_DENIED','old assignee cannot complete stale task');
reset role;update public.membership_locations set capabilities=array['worklists.read']where membership_id=pg_temp.id(201);
set local role authenticated;select pg_temp.claim(3);
select is(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',false,false)#>'{rows,0,patient_id}','null','reduced reader receives no patient id');
select is(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',false,false)#>'{rows,0,patient_name}','null','reduced reader receives no patient name');
select throws_ok($$select pg_temp.task(900,2,'complete',923)$$,'42501','DOCTOR_ACCESS_DENIED','exact receipt replay rechecks current patient grant');
select pg_temp.claim(1);
select throws_ok($$select pg_temp.task(902,0,'create',928,pg_temp.task_input())$$,'42501','DOCTOR_ACCESS_DENIED','patient-linked task cannot be assigned to reduced reader');
select is(pg_temp.task(902,0,'create',928,pg_temp.task_input(3,false))->>'state','assigned','reduced reader remains eligible for general tasks');
select throws_ok($$select public.doctor_archive_location(pg_temp.practice(),pg_temp.location(),1,pg_temp.id(929))$$,'23503','DOCTOR_LOCATION_HAS_DEPENDENCIES','active work prevents clinic archive');
select pg_temp.claim(3);select is(pg_temp.task(902,1,'complete',930)->>'state','completed','general completion needs no patient permission');
reset role;update public.memberships set status='revoked',version=version+1 where id=pg_temp.id(201);
set local role authenticated;select pg_temp.claim(3);
select throws_ok($$select public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',false,false)$$,'42501','DOCTOR_ACCESS_DENIED','C03: revoked assignee cannot read open worklist');
select throws_ok($$select pg_temp.task(902,1,'complete',930)$$,'42501','DOCTOR_ACCESS_DENIED','revoked assignee cannot replay a completed receipt');
select pg_temp.claim(1);
select is(pg_temp.task(901,2,'cancel',931,'{"reason":"no_longer_needed"}')->>'state','cancelled','manager cancels general workload explicitly');
select throws_ok($$select * from public.administrative_tasks$$,'42501',null,'direct protected task reads denied');
select throws_ok($$update public.administrative_task_events set reason='correction'$$,'42501',null,'direct history writes denied');
select is(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'completed',false,false)->>'total','2','status count uses the same complete authoritative cohort');
select is(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',true,false)->>'total','1','mine filter uses current assignee independent of original creator');
select pg_temp.task(n,0,'create',n+1000,pg_temp.task_input(1,false))from generate_series(1000,1020)n;
select is(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),1,'all',false,false)->>'total','24','totals include records outside the current page');
select is(jsonb_array_length(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),1,'all',false,false)->'rows'),4,'last page agrees with full population');
select is(public.doctor_worklist(pg_temp.practice(),pg_temp.location(),0,'all',false,true)->>'total','0','future due clocks are not overdue');
reset role;
select is((select count(*)::integer from public.administrative_task_events where task_id=pg_temp.id(900)),3,'immutable task history has one event per version');
select is((select count(*)::integer from doctor_private.command_receipts where command_key=pg_temp.id(927)),0,'denied stale completion leaves no receipt');
select ok(not exists(select 1 from information_schema.columns where table_schema='public'and table_name in('administrative_tasks','administrative_task_events')and column_name in('notes','diagnosis','message','clinical_priority')),'administrative storage has no clinical or delivery fields');
select * from finish();rollback;
